<script setup lang="ts">import { reactive,onMounted } from 'vue';import AppHeader from '../../components/AppHeader.vue';import BottomAction from '../../components/BottomAction.vue';import UserAvatar from '../../components/UserAvatar.vue';import { useAppStore } from '../../stores/app';import { back } from '../../utils/ui';const store=useAppStore();const form=reactive({nickname:'',realName:'',avatarUrl:'',college:'',major:'',grade:'',bio:''});onMounted(async()=>{await store.bootstrap();const m=store.me;if(m)Object.assign(form,{nickname:m.nickname||'',realName:m.realName||'',avatarUrl:m.avatarUrl||'',college:m.college||'',major:m.major||'',grade:m.grade||'',bio:m.bio||''})});async function submit(){if(!form.nickname.trim())return uni.showToast({title:'昵称不能为空',icon:'none'});try{await store.updateProfile(form);back()}catch{}}</script>
<template><view class="app-shell no-tabs edit-page"><AppHeader title="编辑资料" backable/><view class="avatar-edit"><UserAvatar :name="form.nickname" :src="form.avatarUrl" size="lg"/><text class="muted">头像 URL 可在下方填写</text></view><view class="field"><text class="field-label">昵称</text><input v-model="form.nickname" class="input"/></view><view class="field"><text class="field-label">真实姓名</text><input v-model="form.realName" class="input"/></view><view class="field"><text class="field-label">头像 URL（可选）</text><input v-model="form.avatarUrl" class="input"/></view><view class="field"><text class="field-label">学院</text><input v-model="form.college" class="input"/></view><view class="grid-two"><view class="field"><text class="field-label">专业</text><input v-model="form.major" class="input"/></view><view class="field"><text class="field-label">年级</text><input v-model="form.grade" class="input"/></view></view><view class="field"><text class="field-label">个人简介</text><textarea v-model="form.bio" class="textarea"/></view><view v-if="store.error" class="notice notice-error">{{ store.error }}</view><BottomAction><button class="btn btn-primary btn-block" @click="submit">保存资料</button></BottomAction></view></template><style scoped>.edit-page{padding-bottom:6.5rem}.avatar-edit{display:flex;flex-direction:column;align-items:center;gap:.5rem;padding:1rem}.field{margin-top:1rem}</style>
